// Verifies the signature Convex puts on every loan event. The secret lives in the LENDLOOP_WEBHOOK_SECRET env var.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
let raw;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (error) {
  // Fallback when the raw body is not kept as binary: Convex sends JSON.stringify output, which round-trips byte for byte.
  raw = JSON.stringify(item.json.body);
}
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const reject = (reason) => {
  console.warn('[LendLoop] rejected webhook call:', reason);
  return [{ json: { valid: false } }];
};
if (!secret) return reject('LENDLOOP_WEBHOOK_SECRET is not set');
if (!/^\d{10}$/.test(timestamp)) return reject('missing or malformed timestamp');
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) return reject('timestamp outside replay window');
const expected = Buffer.from('sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest('hex'));
const received = Buffer.from(signature);
if (expected.length !== received.length || !crypto.timingSafeEqual(expected, received)) return reject('bad signature');
return [{ json: { valid: true, event: JSON.parse(raw) } }];

// Turns the minimal event into one line for one person. The payload carries no email or contact data.
const e = $json.event;
const name = e.recipient.firstName;
const tool = e.loan.toolName;
const dates = e.loan.startDate + ' to ' + e.loan.endDate;
const messages = {
  'loan.requested': name + ', a neighbor asked to borrow your ' + tool + ' (' + dates + '). Open LendLoop to approve or decline.',
  'loan.approved': name + ', your request for the ' + tool + ' (' + dates + ') was approved.',
  'loan.declined': name + ', your request for the ' + tool + ' (' + dates + ') was declined.',
  'loan.cancelled': name + ', a request for your ' + tool + ' (' + dates + ') was cancelled by the borrower.',
  'loan.returned': name + ', the ' + tool + ' was marked returned. Thanks for borrowing!',
};
return { json: { eventId: e.eventId, type: e.type, clerkUserId: e.recipient.clerkUserId, text: messages[e.type] || ('Update on ' + tool + ': ' + e.type) } };

// Mock channel: the notification is written to the n8n log and kept in the execution data.
console.log('[LendLoop notification]', JSON.stringify({ eventId: $json.eventId, to: $json.clerkUserId, text: $json.text }));
return { json: { ...$json, channel: 'mock', deliveredAt: new Date().toISOString() } };
